async function optimizeProductImage(file:File):Promise<File>{
 if(file.type==='image/gif')return file;
 try{const bitmap=await createImageBitmap(file);const max=1400,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();return file}ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/webp',0.82));if(!blob||blob.size>=file.size)return file;return new File([blob],file.name.replace(/\\.[^.]+$/,'')+'.webp',{type:'image/webp'})}catch{return file}
}
